export function trackCodeParts(code) {
    const digits = (code || '').replace(/\D/g, '');
    if (digits.length < 7) return { fid: 0, prefix: '' };
    return { fid: parseInt(digits.slice(-7), 10) || 0, prefix: digits.slice(0, 9) };
}
// התאמה רשמית מאומתת כפולה: FUND_ID וגם parentId (ח.פ היצרן) - מונע התנגשות מזהים בין מאגרים.
export function boundOfficial(table, fid, prefix) {
    const o = fid > 0 ? table[fid] : null;
    return o && String(o.parentId) === prefix ? o : null;
}
// 7 הספרות האחרונות כמספר (לשימוש השלמות exposure-extra); null כשאין קוד תקין.
export function fundIdFromTrackCode(code) {
    const { fid } = trackCodeParts(code);
    return fid > 0 ? fid : null;
}
